<?php

declare(strict_types=1);
session_start(); header('Content-Type: application/json; charset=utf-8'); require_once __DIR__ . '/../../../config/database.php';
$userId = (int) ($_SESSION['user_id'] ?? 0); if ($userId < 1) { http_response_code(401); echo json_encode(['error' => 'Authentification requise.']); exit; }
$user = $pdo->prepare("SELECT role FROM users WHERE id = :id AND is_active = 1 LIMIT 1"); $user->execute(['id' => $userId]); if ($user->fetchColumn() !== 'artisan') { http_response_code(403); echo json_encode(['error' => 'Accès réservé aux artisans.']); exit; }
$artisan = $pdo->prepare("SELECT id FROM artisan_profiles WHERE user_id = :user_id AND verification_status = 'verified' LIMIT 1"); $artisan->execute(['user_id' => $userId]); $artisanId = (int) $artisan->fetchColumn(); if (!$artisanId) { http_response_code(403); echo json_encode(['error' => 'Votre profil doit être vérifié.']); exit; }
$statement = $pdo->prepare("SELECT q.id, q.title, q.description, q.category, q.city, q.estimated_budget, q.deadline, q.project_address, q.created_at, EXISTS(SELECT 1 FROM quote_responses qr WHERE qr.quote_id = q.id AND qr.artisan_id = :artisan_id_exists) AS has_responded FROM quotes q WHERE q.quote_type = 'tender' AND q.status = 'open' AND (q.category IS NULL OR q.category = (SELECT category FROM artisan_profiles WHERE id = :artisan_id_category)) AND (q.city IS NULL OR q.city = (SELECT city FROM artisan_profiles WHERE id = :artisan_id_city)) ORDER BY q.created_at DESC"); $statement->execute(['artisan_id_exists' => $artisanId, 'artisan_id_category' => $artisanId, 'artisan_id_city' => $artisanId]); $quotes = array_map(static function (array $quote): array { return ['id' => (int) $quote['id'], 'title' => $quote['title'], 'description' => $quote['description'], 'category' => $quote['category'], 'city' => $quote['city'], 'budget' => $quote['estimated_budget'] !== null ? (float) $quote['estimated_budget'] : null, 'deadline' => $quote['deadline'], 'address' => $quote['project_address'], 'createdAt' => $quote['created_at'], 'hasResponded' => (bool) $quote['has_responded']]; }, $statement->fetchAll()); echo json_encode(['success' => true, 'data' => $quotes]);
